set-variable.value:
@{
    var source = context.LastError == null ? string.Empty : context.LastError.Source ?? string.Empty;
    if (source.Contains("validate-azure-ad-token")) return 401;
    if (source.Contains("validate-content")) return 400;
    if (source.Contains("llm-content-safety")) return 403;
    if (source.Contains("llm-token-limit")) return 429;
    return 500;
  }

@{
        var capSeconds = int.Parse("{{riverside-max-retry-after-seconds}}");
        var policyDelay = Convert.ToInt32(context.Variables.GetValueOrDefault("riversideTokenRetryAfter", 1));
        return Math.Max(1, Math.Min(capSeconds, policyDelay));
      }

return-response.set-body:
@{
          var traceId = (string)context.Variables.GetValueOrDefault("riversideTraceId", Guid.NewGuid().ToString("N"));
          return new JObject(
            new JProperty("error", new JObject(
              new JProperty("code", "overloaded"),
              new JProperty("message", "The tenant token rate limit has been reached."),
              new JProperty("type", "capacity_error"),
              new JProperty("param", null),
              new JProperty("retryable", true),
              new JProperty("retry_after_seconds", (int)context.Variables["riversidePolicyRetryAfter"]))),
            new JProperty("trace", new JObject(
              new JProperty("trace_id", traceId),
              new JProperty("retry_count", 0)))
          ).ToString(Newtonsoft.Json.Formatting.None);
        }

@{
          var status = (int)context.Variables["riversidePolicyErrorStatus"];
          var traceId = (string)context.Variables.GetValueOrDefault("riversideTraceId", Guid.NewGuid().ToString("N"));
          var code = status == 401 ? "unauthorized" : status == 400 ? "invalid_request" : status == 403 ? "policy_violation" : "internal_error";
          var type = status == 401 ? "authentication_error" : status == 400 ? "request_error" : status == 403 ? "policy_error" : "service_error";
          var message = status == 401 ? "Access token is missing or invalid." : status == 400 ? "The request does not satisfy the API contract." : status == 403 ? "The request was blocked by gateway policy." : "The gateway could not complete the request.";
          return new JObject(
            new JProperty("error", new JObject(
              new JProperty("code", code),
              new JProperty("message", message),
              new JProperty("type", type),
              new JProperty("param", null),
              new JProperty("retryable", false))),
            new JProperty("trace", new JObject(
              new JProperty("trace_id", traceId),
              new JProperty("retry_count", 0)))
          ).ToString(Newtonsoft.Json.Formatting.None);
        }
